create type case_state as enum ('NEW','ROUTED','CONTEXT_BUILT','INVESTIGATING','EVIDENCE_GAP','CONTRADICTION','EVIDENCE_READY','DECISION_READY','APPROVAL_REQUIRED','ACTION_EXECUTING','VERIFYING','RESOLVED','REOPENED','ESCALATED','FAILED');
create table cases (case_id text primary key, customer_id text not null, ticket_id text, raw_complaint text not null, primary_intent text, secondary_intent text, domain text[], urgency text, sentiment text, sla_state text, status case_state not null default 'NEW', current_stage text, risk_level text, authorization_state text, action_status text, verification_status text, final_state text, escalation_reason text, reopened_count int not null default 0, parent_case_id text references cases(case_id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table case_twins (case_id text primary key references cases(case_id), twin jsonb not null, created_at timestamptz not null default now());
create table evidence_ledger (evidence_id text primary key, case_id text not null references cases(case_id), source_system text not null, source_record_id text not null, source_type text not null, field_name text not null, value jsonb not null, authority_level text not null, observed_at timestamptz not null, retrieved_at timestamptz not null, freshness_status text not null, retrieval_method text not null, relevance text not null, status text not null, created_at timestamptz not null default now());
create table decisions (decision_id text primary key, case_id text not null references cases(case_id), contract_hash text not null, contract_version text not null, evidence_ids text[] not null, policy_id text, policy_version text, risk_score int not null, risk_factors jsonb not null, auth_state text not null, decision text not null, reason_codes text[] not null, created_at timestamptz not null default now());
create table approvals (approval_id text primary key, decision_id text not null references decisions(decision_id), case_id text not null references cases(case_id), contract_hash text not null, action_type text not null, target_id text not null, amount numeric, policy_version text, risk_score int, requested_at timestamptz not null default now(), expires_at timestamptz, approved_by text, approval_status text not null);
create table actions (action_id text primary key, case_id text not null references cases(case_id), contract_hash text not null, decision_id text references decisions(decision_id), action_type text not null, target_id text not null, amount numeric, currency text, idempotency_key text not null unique, status text not null, retry_count int not null default 0, error_code text, request_payload jsonb, response_payload jsonb, simulated boolean not null default true, created_at timestamptz not null default now(), completed_at timestamptz);
create table idempotency_ledger (idempotency_key text primary key, case_id text not null references cases(case_id), action_type text not null, target_id text not null, contract_hash text not null, status text not null, action_id text references actions(action_id), result_payload jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table verifications (verification_id text primary key, action_id text not null references actions(action_id), case_id text not null references cases(case_id), authoritative_source text not null, evidence_ids text[] not null, expected_postconditions jsonb not null, observed_state jsonb not null, predicate_results jsonb not null, result text not null, failure_reason text, verified_at timestamptz not null default now());
create table resolution_passports (passport_id text primary key, case_id text not null references cases(case_id), reported_problem text, actual_problem text, evidence_ids text[], decision_id text references decisions(decision_id), policy_id text, risk_level text, action_id text references actions(action_id), action_result jsonb, verification_id text references verifications(verification_id), final_state text, created_at timestamptz not null default now());
create table outcome_memory (memory_id text primary key, case_id text not null references cases(case_id), problem_pattern text, evidence_summary text, action_type text, outcome text, verification_status text, policy_reference text, created_at timestamptz not null default now());
create table case_events (event_id text primary key, case_id text not null references cases(case_id), event_type text not null, payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table synthetic_customers (customer_id text primary key, label text not null);
create table synthetic_products (product_id text primary key, name text, label text not null);
create table synthetic_orders (order_id text primary key, customer_id text references synthetic_customers(customer_id), payment_id text, status text not null, error_code text, label text not null);
create table synthetic_payments (payment_id text primary key, customer_id text references synthetic_customers(customer_id), amount numeric not null, currency text not null, status text not null, label text not null);
create table synthetic_refunds (refund_id text primary key, payment_id text references synthetic_payments(payment_id), amount numeric not null, currency text not null, status text not null, label text not null);
create table synthetic_tickets (ticket_id text primary key, customer_id text references synthetic_customers(customer_id), body text, label text not null);
create table synthetic_ticket_messages (message_id text primary key, ticket_id text references synthetic_tickets(ticket_id), body text, label text not null);
create table policies (policy_id text primary key, version text not null, rule_text text not null, label text not null);
create table system_events (event_id text primary key, service text not null, event_type text not null, occurred_at timestamptz not null, label text not null);
create table historical_resolutions (resolution_id text primary key, problem_pattern text not null, error_code text, outcome text, label text not null);
